mapper.insert:
INSERT INTO ROOM_CALENDAR ( ROOM_SN, STAY_DATE, TOTAL_QTY, PRICE_AMT, CLOSED_YN, REG_DT, MDFCN_DT, RGTR_SN ) VALUES
(#{roomSn}, #{d}, #{totalQty}, #{priceAmt}, #{closedYn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{actorSn})
ON DUPLICATE KEY UPDATE TOTAL_QTY = VALUES(TOTAL_QTY), PRICE_AMT = VALUES(PRICE_AMT), CLOSED_YN = VALUES(CLOSED_YN), MDFCN_DT = UTC_TIMESTAMP(6), MDFR_SN = #{actorSn}

INSERT INTO ROOM_CALENDAR ( ROOM_SN, STAY_DATE, TOTAL_QTY, PRICE_AMT, CLOSED_YN, REG_DT, MDFCN_DT, RGTR_SN ) VALUES
(#{roomSn}, #{d}, #{totalQty}, #{priceAmt}, 'N', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{actorSn})
ON DUPLICATE KEY UPDATE TOTAL_QTY = VALUES(TOTAL_QTY), PRICE_AMT = VALUES(PRICE_AMT), MDFCN_DT = UTC_TIMESTAMP(6), MDFR_SN = #{actorSn}

mapper.select:
SELECT ROOM_CALENDAR_SN, ROOM_SN, STAY_DATE, TOTAL_QTY, SOLD_QTY, PRICE_AMT, CLOSED_YN, CLOSE_RSN
  FROM ROOM_CALENDAR
 WHERE ROOM_SN = #{roomSn}
   AND STAY_DATE BETWEEN #{startDate} AND #{endDate}
 ORDER BY STAY_DATE

