(#{roomSn}, #{d}, 0, 0, 'Y', #{closeRsn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{actorSn})
ON DUPLICATE KEY UPDATE CLOSED_YN = 'Y', CLOSE_RSN = #{closeRsn}, MDFCN_DT = UTC_TIMESTAMP(6), MDFR_SN = #{actorSn}

